templates.query_text:
mutation BulkUpdateTodoStatus($todoIds: [ID!]!, $newStatus: String!, $completedAt: String) {
  bulkUpdateNodes(
    nodeIds: $todoIds
    updates: [
      { attributeName: "status", value: $newStatus }
      { attributeName: "completed_at", value: $completedAt }
    ]
  ) {
    success
    updatedCount
    totalCount
    errors {
      message
      nodeId
    }
    nodes {
      id
      content
      attributes {
        name
        value
      }
    }
  }
}

mutation CreateTodo($input: CreateNodeInput!) {
  createNode(input: $input) {
    success
    node {
      id
      content
      createdAt
      updatedAt
      attributes {
        id
        value
        attribute {
          id
          name
          type
        }
      }
    }
    errors {
      message
      field
    }
  }
}

mutation DeleteTodo($todoId: ID!) {
  deleteNode(id: $todoId) {
    success
    errors {
      message
    }
  }
}

mutation UpdateTodo($id: ID!, $input: UpdateNodeInput!) {
  updateNode(id: $id, input: $input) {
    success
    node {
      id
      content
      createdAt
      updatedAt
      attributes {
        id
        value
        attribute {
          id
          name
          type
        }
      }
    }
    errors {
      message
      field
    }
  }
}

templates.variables_schema:
{
  "type": "object",
  "properties": {
    "id": {
      "type": "string",
      "description": "Todo node ID to update"
    },
    "input": {
      "type": "object",
      "properties": {
        "content": {
          "type": "string",
          "description": "Updated todo title/content"
        }
      }
    }
  },
  "required": [
    "id",
    "input"
  ]
}
